//! The bundled emoji: Unicode emoji 18.0 with CLDR release-49's English names and keywords,
//! generated by `generate.py` into `emoji.tsv` (Unicode License V3, `LICENSE-Unicode.txt`).
//!
//! Fully-qualified emoji only, with no skin tone variants (deviation D2) and no Component
//! group. [`unicode`] caps them by the Emoji version they arrived in: a font draws only the
//! emoji it knows, and Rune can't say which those are (draft U-C20d-1), so the host picks the
//! newest version its users' fonts have. [`DEFAULT_VERSION`] is 15.1, which Noto Color Emoji
//! has drawn since 2023 (Ubuntu 24.04's `fonts-noto-color-emoji` included).

use std::sync::OnceLock;

use super::data::{Choice, PickerCategory, PickerItem, PickerSource};

#[cfg(test)]
mod tests;

/// The Emoji version [`unicode`] keeps by default.
pub const DEFAULT_VERSION: f32 = 15.1;

/// One bundled emoji.
#[derive(Debug)]
struct Record {
    glyph: &'static str,
    version: f32,
    name: &'static str,
    keywords: Vec<&'static str>,
    group: usize,
}

/// The groups, in order, with a tab key and the emoji each tab draws.
const GROUPS: [(&str, &str, &str); 9] = [
    ("Smileys & Emotion", "smileys", "😀"),
    ("People & Body", "people", "👋"),
    ("Animals & Nature", "nature", "🐻"),
    ("Food & Drink", "food", "🍔"),
    ("Travel & Places", "travel", "✈\u{fe0f}"),
    ("Activities", "activities", "⚽"),
    ("Objects", "objects", "💡"),
    ("Symbols", "symbols", "❤\u{fe0f}"),
    ("Flags", "flags", "🏁"),
];

fn records() -> &'static [Record] {
    static RECORDS: OnceLock<Vec<Record>> = OnceLock::new();
    RECORDS.get_or_init(|| parse(include_str!("emoji.tsv")))
}

fn parse(tsv: &'static str) -> Vec<Record> {
    let mut group = None;
    let mut out = Vec::new();
    for line in tsv.lines() {
        // A comment is `# ` and text: the keycap #️⃣ starts with `#` too.
        if line.starts_with("# ") || line.is_empty() {
            continue;
        }
        if let Some(name) = line.strip_prefix('@') {
            group = GROUPS.iter().position(|(g, _, _)| *g == name);
            continue;
        }
        let Some(group) = group else { continue };
        let mut fields = line.split('\t');
        let (Some(glyph), Some(version), Some(name)) =
            (fields.next(), fields.next(), fields.next())
        else {
            continue;
        };
        let keywords = fields
            .next()
            .map(|k| k.split('|').filter(|w| !w.is_empty()).collect())
            .unwrap_or_default();
        out.push(Record {
            glyph,
            version: version.parse().unwrap_or(f32::INFINITY),
            name,
            keywords,
            group,
        });
    }
    out
}

/// The bundled emoji up to Emoji `max_version` (15.1: [`DEFAULT_VERSION`]), one category per
/// Unicode group, each emoji named and keyworded in English. Parsed once per process.
///
/// Used by: hosts (`PickerSource::emoji`).
pub(super) fn unicode(max_version: f32) -> PickerSource {
    let categories = GROUPS
        .iter()
        .map(|&(name, key, glyph)| PickerCategory::new(key, name, Choice::emoji(glyph)))
        .collect();
    let items = records()
        .iter()
        .filter(|r| r.version <= max_version + 1e-3)
        .map(|r| {
            PickerItem::new(Choice::emoji(r.glyph), r.name, r.group)
                .keywords(r.keywords.iter().copied())
        })
        .collect();
    PickerSource::new(categories, items)
}

impl PickerSource {
    /// The bundled emoji (Unicode 18.0 data, CLDR release-49 English names and keywords) up
    /// to Emoji `max_version`, one category per Unicode group. Pass
    /// [`DEFAULT_VERSION`] (15.1) unless the host knows its users' fonts draw newer ones.
    pub fn emoji(max_version: f32) -> Self {
        unicode(max_version)
    }
}
